#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9;
const int T = 150;

struct Edge {
    int to, rev, cap, flow, cost;
};

vector<vector<Edge>> g;
vector<int> pot, dist, pv, pe;

void add_edge(int u, int v, int cap, int cost) {
    Edge a{v, (int)g[v].size(), cap, 0, cost};
    Edge b{u, (int)g[u].size(), 0, 0, -cost};
    g[u].push_back(a);
    g[v].push_back(b);
}

pair<int, int> min_cost_flow(int s, int t) {
    int n = (int)g.size();
    pot.assign(n, 0);
    dist.resize(n);
    pv.resize(n);
    pe.resize(n);

    int flow = 0, flow_cost = 0;

    while (true) {
        fill(dist.begin(), dist.end(), INF);
        dist[s] = 0;

        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
        pq.push({0, s});

        while (!pq.empty()) {
            auto cur = pq.top();
            pq.pop();
            int d = cur.first;
            int u = cur.second;

            if (d != dist[u]) continue;

            for (int i = 0; i < (int)g[u].size(); ++i) {
                Edge &e = g[u][i];
                if (e.cap - e.flow <= 0) continue;

                int nd = d + e.cost + pot[u] - pot[e.to];
                if (nd < dist[e.to]) {
                    dist[e.to] = nd;
                    pv[e.to] = u;
                    pe[e.to] = i;
                    pq.push({nd, e.to});
                }
            }
        }

        if (dist[t] == INF) break;

        for (int i = 0; i < n; ++i) pot[i] += dist[i];

        // Every augmenting path must begin with an unused capacity-1 source edge,
        // so the bottleneck is always exactly one unit.
        int add = 1;

        flow += add;
        for (int v = t; v != s; v = pv[v]) {
            Edge &e = g[pv[v]][pe[v]];
            e.flow += add;
            g[v][e.rev].flow -= add;
            flow_cost += add * e.cost;
        }
    }

    return {flow, flow_cost};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    int N = n * T;
    g.assign(N + 2, {});

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < T - 1; ++j) {
            add_edge(i * T + j, i * T + j + 1, INF, c);
        }
    }

    for (int i = 0; i < T; ++i) {
        add_edge(i, N + 1, INF, 0);
    }

    for (int i = 0; i < k; ++i) {
        int x;
        cin >> x;
        --x;
        add_edge(N, x * T, 1, 0);
    }

    for (int i = 0; i < m; ++i) {
        int x, y;
        cin >> x >> y;
        --x;
        --y;
        for (int j = 0; j < T - 1; ++j) {
            int cur = 1;
            for (int z = 0; z < k; ++z) {
                add_edge(x * T + j, y * T + j + 1, 1, cur * d + c);
                add_edge(y * T + j, x * T + j + 1, 1, cur * d + c);
                cur += 2;
            }
        }
    }

    pair<int, int> ans = min_cost_flow(N, N + 1);
    assert(ans.first == k);
    cout << ans.second << endl;
    return 0;
}
